    "language": "xml",
    "category": "Manifest & Resources",
    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    xmlns:tools=\"http://schemas.android.com/tools\">\n\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n    \n    <!--\n        Broad package visibility is required by the core app-management feature:\n        the whitelist and force-stop candidate screens enumerate installed apps locally,\n        then exclude system apps, this app, and critical system roles before any action.\n        Keep this permission narrowly scoped to that user-facing functionality.\n    -->\n    <uses-permission\n        android:name=\"android.permission.QUERY_ALL_PACKAGES\"\n        tools:ignore=\"QueryAllPackagesPermission\" />\n\n    <application\n        android:allowBackup=\"true\"\n        android:dataExtractionRules=\"@xml/data_extraction_rules\"\n        android:fullBackupContent=\"@xml/backup_rules\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.StatusBarManager\">\n\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:label=\"@string/app_name\"\n            android:theme=\"@style/Theme.StatusBarManager\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Home Screen Widget Provider (Objective 4) -->\n        <receiver\n            android:name=\".widget.HushButtonIconWidgetProvider\"\n            android:exported=\"true\"\n            android:label=\"@string/widget_hush_button_name\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/syshush_hush_button_widget_info\" />\n        </receiver>\n\n        <receiver\n            android:name=\".widget.StopAppsWidgetProvider\"\n            android:exported=\"true\"\n            android:label=\"@string/widget_stop_apps_name\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/syshush_stop_apps_widget_info\" />\n        </receiver>\n\n        <receiver\n            android:name=\".widget.StatusBarOnlyWidgetProvider\"\n            android:exported=\"true\"\n            android:label=\"@string/widget_status_bar_only_name\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/syshush_status_bar_widget_info\" />\n        </receiver>\n\n        <receiver\n            android:name=\".widget.StatusBarWidgetProvider\"\n            android:exported=\"true\"\n            android:label=\"@string/widget_name\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n                <action android:name=\"com.statusbarmanager.app.widget.ACTION_WIDGET_TOGGLE\" />\n                <action android:name=\"com.statusbarmanager.app.widget.ACTION_WIDGET_FORCE_STOP\" />\n                <action android:name=\"com.statusbarmanager.app.widget.ACTION_WIDGET_STATUS_BAR_ONLY\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/status_bar_widget_info\" />\n        </receiver>\n\n        <!-- Dedicated Android Accessibility Service for Automating Status Bar Settings & Force Stop -->\n        <service\n            android:name=\".service.StatusBarAccessibilityService\"\n            android:permission=\"android.permission.BIND_ACCESSIBILITY_SERVICE\"\n            android:exported=\"true\"\n            android:label=\"@string/accessibility_service_label\"\n            android:description=\"@string/accessibility_service_description\">\n            <intent-filter>\n                <action android:name=\"android.accessibilityservice.AccessibilityService\" />\n            </intent-filter>\n\n            <meta-data\n                android:name=\"android.accessibilityservice\"\n                android:resource=\"@xml/status_bar_accessibility_service_config\" />\n        </service>\n\n    </application>\n\n</manifest>\n"
