    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<vector xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:width=\"48dp\"\n    android:height=\"48dp\"\n    android:viewportWidth=\"48\"\n    android:viewportHeight=\"48\">\n\n    <!-- Top Status Bar Horizon Line -->\n    <path\n        android:strokeColor=\"#38BDF8\"\n        android:strokeWidth=\"2.5\"\n        android:strokeLineCap=\"round\"\n        android:pathData=\"M10,13 L22,13\" />\n\n    <!-- Dissolving Status Indicators (Calm dots) -->\n    <path\n        android:fillColor=\"#38BDF8\"\n        android:pathData=\"M27,13 A1.6,1.6 0 1 0 27,13.01\" />\n\n    <path\n        android:fillColor=\"#22D3EE\"\n        android:fillAlpha=\"0.75\"\n        android:pathData=\"M33,13 A1.5,1.5 0 1 0 33,13.01\" />\n\n    <path\n        android:fillColor=\"#818CF8\"\n        android:fillAlpha=\"0.5\"\n        android:pathData=\"M38,13 A1.4,1.4 0 1 0 38,13.01\" />\n\n    <!-- Center System Control: Calm Hush Toggle Track -->\n    <path\n        android:fillColor=\"#0F172A\"\n        android:strokeColor=\"#0284C7\"\n        android:strokeWidth=\"2\"\n        android:pathData=\"M16,24 L32,24 A5,5 0 0 1 37,29 L37,29 A5,5 0 0 1 32,34 L16,34 A5,5 0 0 1 11,29 L11,29 A5,5 0 0 1 16,24 Z\" />\n\n    <!-- Active Hush Thumb with Glow -->\n    <path\n        android:fillColor=\"#22D3EE\"\n        android:pathData=\"M32,29 A3.5,3.5 0 1 0 25,29 A3.5,3.5 0 1 0 32,29 Z\" />\n\n    <!-- Quiet Shield Arc Base -->\n    <path\n        android:strokeColor=\"#6366F1\"\n        android:strokeWidth=\"1.8\"\n        android:strokeLineCap=\"round\"\n        android:pathData=\"M17,39 C21,41.5 27,41.5 31,39\" />\n\n</vector>\n"
